const row = $input.first().json;

if (!row || !row.resultado) {
  return [{ json: {
    total: 0,
    plantillas: [],
    mensaje: 'No hay plantillas activas disponibles.'
  }}];
}

let plantillas;
try {
  plantillas = JSON.parse(row.resultado);
} catch (e) {
  return [{ json: {
    total: 0,
    plantillas: [],
    mensaje: 'Error al procesar las plantillas.'
  }}];
}

if (!plantillas || plantillas.length === 0) {
  return [{ json: {
    total: 0,
    plantillas: [],
    mensaje: 'No hay plantillas activas disponibles.'
  }}];
}

const parse = v => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  try { return JSON.parse(v); } catch { return []; }
};

return [{ json: {
  total: plantillas.length,
  plantillas: plantillas.map(t => {
    const components = parse(t.components).map(d => ({
      det_id:           d.det_id,
      component_type:   d.component_type,
      component_format: d.component_format,
      text_content:     d.text_content,
      sort_order:       d.sort_order,
      media_identifier: d.media_identifier || null,
      buttons:          parse(d.buttons),
      examples:         parse(d.examples)
    }));

    const body    = components.find(c => c.component_type === 'BODY');
    const header  = components.find(c => c.component_type === 'HEADER');
    const footer  = components.find(c => c.component_type === 'FOOTER');
    const btnComp = components.find(c => c.component_type === 'BUTTONS');

    return {
      template_id:      t.template_id,
      template_name:    t.template_name,
      language:         t.language,
      meta_template_id: t.meta_template_id,
      parameter_format: t.parameter_format,
      header_text:      header?.text_content    || null,
      header_format:    header?.component_format || null,
      body_text:        body?.text_content       || null,
      footer_text:      footer?.text_content     || null,
      variables:        body?.examples           || [],
      buttons:          btnComp?.buttons         || [],
      components
    };
  })
}}];
